const staticData = $getWorkflowStaticData('global');

const cookies = staticData.cookies || [];
const ls = staticData.localStorage || {};
const temSessao = cookies.length > 0;

const code = `export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const URL_BASE = 'https://app.cotadorsimplificado.com.br';
  const log = [];
  const wait = (ms) => new Promise(r => setTimeout(r, ms));

  const savedCookies = ${JSON.stringify(cookies)};
  const savedLocalStorage = ${JSON.stringify(ls)};
  const temSessao = ${temSessao};

  try {
    await page.setViewport({ width: 1280, height: 800 });

    async function fazerLogin() {
      await page.goto(URL_BASE + '/login', { waitUntil: 'networkidle2', timeout: 60000 });
      await wait(3000);
      const emailInput = await page.$('#email_principal');
      if (emailInput) {
        await emailInput.click();
        await emailInput.type(EMAIL, { delay: 30 });
      }
      await wait(1000);
      let buttons = await page.$$('button');
      for (const btn of buttons) {
        const text = await page.evaluate(el => el.textContent, btn);
        if (text && text.includes('Continuar com Email')) {
          await btn.click();
          break;
        }
      }
      await wait(3000);
      await page.waitForSelector('#pwdInput', { timeout: 15000 });
      const senhaInput = await page.$('#pwdInput');
      if (senhaInput) {
        await senhaInput.click();
        await senhaInput.type(SENHA, { delay: 30 });
      }
      await wait(1000);
      buttons = await page.$$('button');
      for (const btn of buttons) {
        const text = await page.evaluate(el => el.textContent.trim(), btn);
        if (text === 'Entrar') {
          await btn.click();
          break;
        }
      }
      await wait(8000);
      log.push('Login OK');
    }

    if (temSessao && savedCookies.length > 0) {
      log.push('Restaurando sessao...');
      await page.goto(URL_BASE, { waitUntil: 'domcontentloaded', timeout: 30000 });
      await page.setCookie(...savedCookies);
      await page.evaluate((ls) => {
        for (const [key, value] of Object.entries(ls)) {
          window.localStorage.setItem(key, value);
        }
      }, savedLocalStorage);
      await page.reload({ waitUntil: 'networkidle2' });
      await wait(3000);
      const loginBtn = await page.$('#email_principal');
      if (!loginBtn) {
        log.push('Sessao restaurada!');
      } else {
        log.push('Sessao expirada, fazendo login...');
        await fazerLogin();
      }
    } else {
      log.push('Sem sessao, fazendo login...');
      await fazerLogin();
    }

    log.push('Clicando Hapvida...');
    const hapvidaImg = await page.$('img[src*="hapvida"]');
    if (hapvidaImg) {
      const parent = await hapvidaImg.evaluateHandle(el => el.closest('.clickable-element') || el.parentElement.parentElement);
      await parent.click();
      await wait(4000);
    }
    log.push('Hapvida OK');

    log.push('Clicando PME...');
    const pme = await page.evaluateHandle(() => [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29')));
    if (pme) await pme.click();
    await wait(3000);
    log.push('PME OK');

    log.push('Preenchendo nome...');
    await page.waitForSelector('#id-nomelead', { timeout: 10000 });
    const nomeInput = await page.$('#id-nomelead');
    if (nomeInput) {
      await nomeInput.click();
      await wait(500);
      await nomeInput.type('teste', { delay: 50 });
    }
    log.push('Nome OK');

    log.push('Avancando 1...');
    const btnAv1 = await page.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan')));
    if (btnAv1) await btnAv1.click();
    await wait(3000);
    log.push('Avancar 1 OK');

    log.push('Preenchendo cidade...');
    await page.waitForSelector('#cidade_nome', { timeout: 10000 });
    const cidadeInput = await page.$('#cidade_nome');
    if (cidadeInput) {
      await cidadeInput.click();
      await wait(500);
      await cidadeInput.type('recife', { delay: 50 });
    }
    await wait(2000);
    await page.keyboard.press('ArrowDown');
    await wait(500);
    await page.keyboard.press('Enter');
    await wait(2000);
    log.push('Cidade OK');

    log.push('Selecionando empresa...');
    const sel = await page.$('select');
    if (sel) {
      await sel.click();
      await wait(500);
      await page.select('select', 'MEI - EMPRESARIO INDIVIDUAL');
    }
    log.push('Empresa OK');

    log.push('Avancando 2...');
    const btnAv2 = await page.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan')));
    if (btnAv2) await btnAv2.click();
    await wait(3000);
    log.push('Avancar 2 OK');

    log.push('Preenchendo faixas...');
    const inputs = await page.$$('.bubble-rg input');
    let preenchidas = 0;
    for (let i = 0; i < Math.min(inputs.length, 10); i++) {
      try {
        await inputs[i].click();
        await inputs[i].type('1');
        preenchidas++;
        await wait(300);
      } catch(e) {}
    }
    log.push('Faixas: ' + preenchidas);

    const cookies = await page.cookies();
    const localStorage = await page.evaluate(() => {
      const items = {};
      for (let i = 0; i < window.localStorage.length; i++) {
        const key = window.localStorage.key(i);
        items[key] = window.localStorage.getItem(key);
      }
      return items;
    });

    const screenshot = await page.screenshot({ encoding: 'base64' });
    return { success: true, log, url: page.url(), cookies, localStorage, screenshot };
  } catch (error) {
    const screenshot = await page.screenshot({ encoding: 'base64' }).catch(() => null);
    return { success: false, error: error.message, log, screenshot };
  }
}`;

return { json: { code } };

const staticData = $getWorkflowStaticData('global');
